const ms = magSite();
const GMU_SURVEY = 'REQUIREMENT: Garmin\'s magnetic-interference survey proves the site before the pocket is cut (GMU 11 held at the site, lights and strobes on and off, avionics and pump on, controls through their travel); if it fails, the site moves before any laminate is cut.';
const GMU_DEF = jRec({ pn: 'LEZ-31-122', nha: 'LEZ-31-120', kind: 'cots', title: 'Garmin GMU 11 magnetometer (left wing)', rev: 'B',
  revs: [{ rev: 'A', date: TODAY, short: 'Initial definition', change: '' }, { rev: 'B', date: '2026-11-19', short: 'Spacing rule → heading-error bound', change: `Coordinator decision (Miles): I2 was a hard 36 in rule from current-carrying wires that no site in this wing meets (the light harness passed ${fx(ms.near.light, 1)} in away). I2 is now a BOUND on the heading error computed from every current-carrying run (${ms.all.runs.length} runs: the wingtip-light triad, the power, starter, ground and strap runs, ignition and P-leads; finite-segment pair fields) plus the moving rudder cable, limit ${MAGP.lim}° (typed): ${fx(ms.errAll, 3)}° as routed; and a recorded requirement that Garmin's magnetic-interference survey proves the site before the pocket is cut. The rudder-cable term (> 10 in) is kept; jmag-site uses the same sum.` }],
  change: `Initial definition. The GMU 11 sat at BL 72, x/c 0.45, 4.9 in from C's rudder conduit and the systems conduit, against a 36 in rule it could not meet. As defined: BL ${L.MAG.bl}, x/c ${L.MAG.x} (ahead of the wing spar), on a 2024-T3 base in a foam-core pocket, brass hardware; the site that maximises the distances found by a sweep of the left wing. The published Garmin distances are NOT met anywhere in this wing (light harness ${fx(ms.near.light, 1)} in, rudder cable ${fx(ms.near.cable, 1)} in against 36 in; engine ${fx(ms.big.engine, 0)} in and main gear ${fx(ms.big.maingear, 0)} in against 98 in); the heading error from the currents and moving metal is computed (jmag-site) and the site is to be proven by Garmin's magnetic-interference survey before the pocket is cut.`,
  vendorMass: `${E.gmu.mass} lb`, datums: [{ id: 'A', what: 'Base level with the wing chord plane' }],
  features: [{ id: 'body', kind: 'profile', label: `${E.gmu.why} (${E.gmu.src})`, tol: 'Level within 3.0° of the cruise attitude, connector within 0.5° of an aircraft axis (G3X IM sec. 13.4, Fig. 13-4)' }, { id: 'bracket', kind: 'profile', label: `2024-T3 ${GMU_BRKT.t} in base ${GMU_BRKT.w} × ${GMU_BRKT.l} in on a G10 pad bonded in a foam-core pocket (Garmin asks for rigid, non-magnetic structure, G5 IM App. D.4; 0.040 in is the published GMU 44 platform minimum, 190-01051-00 rev D p. 1-51); access cover in the lower skin`, tol: '±0.03' }],
  generalNote: 'Distances from the Garmin G3X IM 190-01115-01 rev AV sec. 13.4, Table 13-4 (the GMU 11\'s own table, eight rows: conductors and devices > 100 mA 1.0 m, ferrous < 1 kg 1.0 m, > 1 kg 2.5 m, motors and relays 3.0 m, devices < 100 mA and other magnetometers 0.6 m, conductors < 100 mA 0.4 m); if they cannot be met Garmin requires the magnetometer interference test. The 1° heading-error limit is this design\'s own bound, stricter than Garmin: the survey is pass/fail and the post-install compass swing accepts ±6° on each of 12 headings (G5 MM 190-01112-11 sec. 7.6).', drawingNotes: [GMU_SURVEY],
  material: unitMat('Garmin GMU 11 (010-01788-00) with install kit 011-04349-90'), process: [{ op: 'Survey', spec: 'Magnetic interference survey at the site before cutting the pocket (Garmin procedure), lights and strobes on and off, controls through their travel.' }, { op: 'Install', spec: 'Pocket, G10 pad, base, 4 stainless screws (kit); orientation set in the AXIS; calibrate with the GSU 25C.' }],
  checks: ['jm-gmu', 'jmag-site'], hardware: [{ std: '6-32 × 0.500 pan head 300-series CRES + #6 SS washer + 6-32 nylon-lock nut (Garmin kit 011-04349-90)', qty: 4, each: 0.003, desc: 'mounting hardware (non-magnetic)' }], hardwareNote: '4 × 6-32 stainless (Garmin kit); no steel within 0.5 m (G3X IM sec. 13.4).',
  interfaces: [ifc('I1', 'LEZ-57-110 wing (A)', 'bracket', 'Inside the wing, ahead of the spar', () => { const w = GEO.wing.spar, ok_ = L.MAG.x < w - 0.05; return ok(ok_, `x/c ${L.MAG.x} vs spar ${fx(w, 3)} (pocket, cover and spar-web grommet: A ask, LEZ-57-110 rev E)`); }),
    ifc('I2', 'Every current-carrying run (I\'s light harness, power, starter, ground, ignition) and C\'s rudder conduit', 'body', `BOUND: computed heading error ≤ ${MAGP.lim}° (typed); Garmin's survey proves the site before the pocket is cut; rudder cable > 10 in`, () => { const sv = GMU_DEF.process.some((p) => p.op === 'Survey') && GMU_DEF.drawingNotes.includes(GMU_SURVEY);
      return ok(ms.errAll <= MAGP.lim && ms.near.cable > 10 && sv, `heading error ${fx(ms.errAll, 3)}° from ${ms.all.runs.length} current-carrying runs and the rudder cable (BOUND ≤ ${MAGP.lim}°, typed from memory); nearest light harness ${fx(ms.near.light, 1)} in, rudder cable ${fx(ms.near.cable, 1)} in (published 36 in not met); survey before the pocket is cut ${sv ? 'recorded' : 'NOT recorded'}`); }), ifc('I3', 'Every other part', 'body', '≥ 0.25 in', clr('LEZ-31-122'))],
  sourcing: src('Garmin (AXIS Build-A-System Guide 7.2026)', GAR, E.gmu.cost, 'GMU 11 010-01788-00 $410 (in the LRU kit 010-04556-00); install kit 011-04349-90 $75.', { sourced: true }) });
