{ const nx = (r) => String.fromCharCode(r.charCodeAt(0) + 1), SRC_AUDIT = {
    'LEZ-31-110': { short: 'Source audit: price, envelope BOUND', change: 'Source audit: cost $16,560 (Aircraft Spruce 11-21145; was $6,995 typed); the AXIS installation drawing is not public, so the envelope and the 5.0 lb stay BOUND, to be measured on receipt (the nearest published unit, the GDU 460, is 10.85 × 7.82 × 3.57 in, 4.81 lb).' },
    'LEZ-31-122': { short: 'Source audit: true size, rotated, 8-row table', change: 'Source audit (G3X IM Table 2-4, Table 13-3, 13-4): 2.74 × 3.78 × 0.93 in, 0.302 lb with connectors (1.80 × 2.90 × 1.00, 0.15 lb had been typed); laid with its length across so it fits A\'s pocket (connector inboard, orientation set in the AXIS), base 3.8 × 2.9 in (was 2.6 in long, shorter than the unit); 4 × 6-32 stainless (Garmin kit) for 3 brass; the published distance table has eight rows (four added); the 1° bound is DESIGN, stricter than Garmin (survey pass/fail, swing ±6°). Cost $410.' },
    'LEZ-31-124': { short: 'Source audit: mass, bonding strap', change: 'Source audit: 0.3 lb including its 10 ft lead (0.06 had been typed); mounted through a grounded aluminium strap (a glass doubler gives no ground path, G3X IM 18.3), bond ≤ 2.5 mΩ.' },
    'LEZ-34-114': { short: 'Source audit: GA 35S data', change: 'Source audit (GA 35S IM 190-02466-00 rev 3): 3.34 × 4.71 × 1.00 in, 0.52 lb, 4 × #8-32 × 1.00 SS; the 8 in plane (G3X IM 20.4.5) is met (reach 4.3); the GA 35S manual\'s 7.5 in beyond the perimeter is not adopted for the composite deck (G3X rule, Miles 2026-11-19). Cost $400.' },
    'LEZ-34-110': { short: 'Source audit: CI 105 two-stud mount', change: 'Source audit (Comant CI 105 data sheet): 3.23 in tall, 0.24 lb, the standard two-stud mount (was 4 × #8 and nutplates). Cost $239 (CI-105-16).' },
    'LEZ-34-100': null, 'LEZ-31-130': null, 'LEZ-31-120': null, 'LEZ-31-160': null, 'LEZ-25-160': null, 'LEZ-34-130': null, 'LEZ-25-162': null,
    'LEZ-34-135': { short: 'Source audit: compression tees', change: 'Source audit: AN824 flare tees do not seal on nylon; the tees are Poly-Flo compression tees (Aircraft Spruce Nylaflow page).' },
    'LEZ-23-110': { short: 'Source audit: RG-400 spec loss and mass, BNC dash', change: 'Source audit: RG-400 attenuation at the MIL-DTL-17/128B spec maximum (4.5 / 10.5 / 17 / 23.7 / 28.2 dB per 100 ft) and 0.05 lb/ft (was 0.035); BNC M39012/16-0503 (Amphenol 31-4427). Cost from $5.91/ft.' },
    'LEZ-34-111': { short: 'Source audit: RG-400 spec data; GTX re-route', change: 'Source audit: RG-400 at the spec maximum loss and 0.05 lb/ft; R21 and R23 re-routed for the relocated GTX 45R (shelf rev C), clear of the GSU 25C and ahead of the shelf.' },
    'LEZ-31-121': { short: 'Source audit: CAN 20 m, GSU 25C start', change: 'Source audit (G3X IM 2.3.1.3): the bus limit is 20 m end to end (30 m had been typed), stubs ≤ 0.3 m; the harness now starts at the GSU 25C right of the GTX and drops through the shelf ahead of it.' },
  };
  for (const d of J_DEFS) { const a = d.audit || SRC_AUDIT[d.pn]; if (!a) continue; const r = nx(d.rev); d.revs = [...d.revs, { rev: r, date: '2026-11-19', ...a }]; d.rev = r; delete d.audit; } }
